async function liveDashboardLoad(){const r=await fetch('/api/dashboard',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310'})});const d=await r.json();if(!r.ok)throw Error(d.error);const target=document.getElementById('live-dashboard-data');if(!target)return;target.innerHTML=`<p>Demo · ${esc(d.user)} · ${esc(d.role)} · Calculated ${esc(new Date(d.as_of*1000).toLocaleString())}</p><div class="stats">${d.metrics.map(m=>`<article class="card prose"><h2>${esc(m.name)}</h2><strong style="font-size:2rem">${m.value}</strong><p>${esc(m.calculation)}</p><a href="${m.href}">View records</a></article>`).join('')}</div><section class="card prose"><h2>Demo enrolled courses</h2>${d.courses.map(c=>`<p>${esc(c)} — <a href="#assignments">Course work</a> · <a href="#grades">Grades</a></p>`).join('')||'<p>No active courses.</p>'}</section><section class="card prose"><h2>Demo submission activity</h2>${d.submissions.map(s=>`<p>${esc(s.title)} · ${esc(new Date(s.created*1000).toLocaleString())} · Receipt ${esc(s.id)} · ${s.grade?(s.grade.posted?'Published grade: ':'Draft grade: ')+esc(String(s.grade.score)):'No visible grade'}</p>`).join('')||'<p>No submission receipts.</p>'}</section><section class="card prose"><h2>Demo personal calendar</h2>${d.calendar.map(e=>`<p>${esc(e.event_date)} · ${esc(e.title)}</p>`).join('')||'<p>No saved personal events.</p>'}<a href="#calendar">Manage calendar</a></section><section class="card prose"><h2>Metrics unavailable</h2><ul>${d.unavailable.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section>`;}
const beforeLiveDashboard=render;render=function(){if(location.port==='4180'&&['#dashboard','#live-courses'].includes(location.hash)){document.getElementById('app').innerHTML=integratedShell('dashboard',heading(location.hash==='#live-courses'?'My courses':'Learning dashboard','Demo · Metrics calculated from saved records')+`<section class="card prose"><button class="button secondary" id="live-dashboard-refresh">Refresh records</button><p id="live-dashboard-status" role="status"></p></section><div id="live-dashboard-data">Connect to load your authorized records.</div>`,model.role);bind();if(governedToken)liveDashboardLoad().catch(e=>document.getElementById('live-dashboard-status').textContent=e.message);}else beforeLiveDashboard();};
document.addEventListener('submit',async e=>{if(e.target.id!=='live-dashboard-connect')return;e.preventDefault();governedToken=new FormData(e.target).get('token');e.target.reset();try{await liveDashboardLoad();document.getElementById('live-dashboard-status').textContent='Records loaded.';}catch(err){document.getElementById('live-dashboard-data').textContent='No authorized records loaded.';document.getElementById('live-dashboard-status').textContent=err.message;}});
document.addEventListener('click',async e=>{if(!e.target.closest('#live-dashboard-refresh'))return;try{await liveDashboardLoad();}catch(err){document.getElementById('live-dashboard-data').textContent='No authorized records loaded.';document.getElementById('live-dashboard-status').textContent=err.message;}});render();
